<?php require_once dirname(__DIR__).'/lib.php';admin_required();try{verify_csrf();$id=(int)$_POST['id'];$lt=token();$rt=token();$s=db()->prepare('UPDATE contracts SET lessor_token_hash=?,lessee_token_hash=?,token_expires_at=DATE_ADD(NOW(),INTERVAL ? DAY),updated_at=NOW() WHERE id=?');$s->execute([hash_token($lt),hash_token($rt),(int)cfg('security.token_days'),$id]);$_SESSION['new_lessor_token']=$lt;$_SESSION['new_lessee_token']=$rt;audit($id,'admin','tokens_regenerated');header('Location:view.php?id='.$id);}catch(Throwable $e){die(e($e->getMessage()));}